package com.printflow.identity;
import java.util.*;import java.nio.file.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.core.env.StandardEnvironment;import tools.jackson.databind.json.JsonMapper;import jakarta.mail.*;
/** Explicit owner-authorized local test copy; never used by production HTTP routes. */
public class InvoiceEmailEvidence {
 public static void main(String[] args)throws Exception{
  String url=System.getenv("DB_URL"),recipient=System.getenv("APP_INVOICE_EVIDENCE_RECIPIENT");if(url==null||!url.startsWith("jdbc:postgresql://127.0.0.1:5434/")||recipient==null||!Arrays.asList(System.getenv("APP_MAIL_ALLOWED_RECIPIENTS").split(",")).contains(recipient))throw new IllegalStateException("Use native DB and the explicitly allowed test inbox");
  var db=new JdbcTemplate(new DriverManagerDataSource(url,System.getenv("DB_USERNAME"),System.getenv("DB_PASSWORD")));UUID lead=UUID.fromString(System.getenv("APP_INVOICE_EVIDENCE_LEAD"));var source=db.queryForMap("select f.id,e.public_id from finance_invoices f join enquiries e on e.id=f.enquiry_id where e.id=? and e.customer_name like 'Synthetic%' and e.email like '%@example.test' order by f.invoice_number desc limit 1",lead);UUID invoice=(UUID)source.get("id"),event=UUID.nameUUIDFromBytes(("invoice-evidence:"+invoice+":"+recipient).getBytes(java.nio.charset.StandardCharsets.UTF_8));
  var mail=new CustomerMail(db,System.getenv("APP_MAIL_ENCRYPTION_KEY"),false,"smtp.gmail.com",587,System.getenv().getOrDefault("APP_MAIL_USERNAME",""),System.getenv().getOrDefault("APP_MAIL_PASSWORD",""),"http://127.0.0.1:3000","","",new StandardEnvironment());mail.queueProject(null,lead,recipient,source.get("public_id").toString(),"INVOICE",event,"TEST EVIDENCE ONLY: Razorpay sandbox payment and synthetic print order. No real printing, shipping or money movement. Attached is the exact immutable invoice generated during the UI test.");var row=db.queryForMap("select * from mail_outbox where enquiry_id=? and message_id=?",lead,"<invoice-"+event+"@jdprintex.in>");db.update("update mail_outbox set invoice_id=? where id=?",invoice,row.get("id"));row.put("invoice_id",invoice);var message=mail.compose(row);var parts=new ArrayList<Part>();parts(message,parts);var attachment=parts.stream().filter(p->{try{return Part.ATTACHMENT.equals(p.getDisposition());}catch(Exception e){return false;}}).findFirst().orElseThrow();byte[] attached=attachment.getInputStream().readAllBytes();byte[] original=db.queryForObject("select document_pdf from finance_invoices where id=?",byte[].class,invoice);if(!Arrays.equals(attached,original))throw new IllegalStateException("MIME attachment mismatch");
  Files.write(Path.of("..",".local","razorpay-evidence-invoice.pdf"),original);Path output=Path.of("..",".local","razorpay-email-evidence.json");Files.writeString(output,JsonMapper.builder().build().writeValueAsString(Map.of("outboxId",row.get("id"),"invoiceId",invoice,"mimePdfVerified",true,"pdfSha256",com.printflow.customer.Payments.sha(attached),"filename",attachment.getFileName(),"recipient","configured private test inbox")));System.out.println("Exact invoice MIME PDF verified; one test email queued to the configured private inbox.");
 }
 static void parts(Part part,List<Part> all)throws Exception{if(part.isMimeType("multipart/*")){var m=(Multipart)part.getContent();for(int i=0;i<m.getCount();i++)parts(m.getBodyPart(i),all);}else all.add(part);}
}
